import { IntegerColumn, ReferenceColumn, StringColumn, Table } from '@servicenow/sdk/core'

export const sn_table_app_incoming = Table({
    actions: ['read', 'update', 'create'],
    index: [{ name: 'index', element: 'string_column', unique: false }],
    name: 'sn_table_app_incoming',
    label: 'Incoming Table',
    extends: 'cmdb',
    schema: {
        string_column: StringColumn({
            dropdown: 'none',
            choices: {
                choice1: { label: 'choice1', inactive_on_update: false },
                choice2: { label: 'choice2', inactive_on_update: false },
            },
        }),
        integer_column: IntegerColumn({
            label: 'Integer Column',
            audit: true,
            readOnly: false,
            dropdown: 'suggestion',
            choices: {
                1: { label: 'One', value: '1', inactive_on_update: false },
                2: { label: 'Two', value: '2', inactive_on_update: false },
            },
        }),
        reference_column: ReferenceColumn({ audit: false, readOnly: false, referenceTable: 'task' }),
    },
    display: 'integer_column',
})
